def run(params, grid, demos):
    bg = int(round(params['colors'][0]))
    moving = int(round(params['colors'][1]))
    target = int(round(params['colors'][2]))
    step = int(round(params['motion'][0]))
    zero = int(round(params['motion'][1]))
    out = grid.copy()
    if moving == target or moving == bg or target == bg or step <= zero:
        return out
    red = np.argwhere(grid == moving)
    blue = np.argwhere(grid == target)
    if len(red) == 0 or len(blue) == 0:
        return out
    rlo = np.min(red, axis=0)
    rhi = np.max(red, axis=0)
    blo = np.min(blue, axis=0)
    bhi = np.max(blue, axis=0)
    dr = zero
    dc = zero
    if rlo[0] <= bhi[0] and blo[0] <= rhi[0]:
        if np.mean(red[:, 1]) < np.mean(blue[:, 1]):
            dc = step
        else:
            dc = -step
    else:
        if np.mean(red[:, 0]) < np.mean(blue[:, 0]):
            dr = step
        else:
            dr = -step
    fixed = set()
    for r, c in blue:
        fixed.add((int(r), int(c)))
    positions = red.copy()
    for iteration in range(grid.shape[0] + grid.shape[1]):
        touching = False
        for r, c in positions:
            for delta in params['neighbors']:
                nr = int(r) + int(round(delta[0]))
                nc = int(c) + int(round(delta[1]))
                if (nr, nc) in fixed:
                    touching = True
        if touching:
            break
        candidate = positions + np.array([dr, dc])
        valid = True
        for r, c in candidate:
            if r < zero or c < zero or r >= grid.shape[0] or c >= grid.shape[1] or (int(r), int(c)) in fixed:
                valid = False
        if not valid:
            break
        positions = candidate
    out[grid == moving] = bg
    for r, c in positions:
        out[int(r), int(c)] = moving
    return out

def run(params, grid, demos):
    background = int(round(params['colors'][0]))
    moving = int(round(params['colors'][1]))
    anchor = int(round(params['colors'][2]))
    unit = int(round(params['unit'][0]))
    out = grid.copy()
    if background == moving or moving == anchor or background == anchor or unit <= 0:
        return out
    cells = np.argwhere(grid == moving)
    anchors = np.argwhere(grid == anchor)
    if len(cells) == 0 or len(anchors) == 0:
        return out
    directions = []
    for pair in params['directions']:
        directions.append((int(round(pair[0])), int(round(pair[1]))))
    height, width = grid.shape
    best = None
    best_distance = None
    for dr, dc in directions:
        for distance in range(unit, max(height, width) + unit, unit):
            shifted = []
            valid = True
            touching = False
            for row, col in cells:
                nr = int(row) + dr * distance
                nc = int(col) + dc * distance
                if nr < 0 or nr >= height or nc < 0 or nc >= width:
                    valid = False
                    break
                if grid[nr, nc] == anchor:
                    valid = False
                    break
                shifted.append((nr, nc))
                for ar, ac in directions:
                    rr = nr + ar
                    cc = nc + ac
                    if 0 <= rr < height and 0 <= cc < width:
                        if grid[rr, cc] == anchor:
                            touching = True
            if valid and touching:
                if best_distance is None or distance < best_distance:
                    best_distance = distance
                    best = shifted
                break
    if best is not None:
        for row, col in cells:
            out[row, col] = background
        for row, col in best:
            out[row, col] = moving
    return out

def cover(remaining, placements, lookup):
    if not remaining:
        return []
    best = None
    for cell in remaining:
        choices = [i for i in lookup[cell] if placements[i][1].issubset(remaining)]
        if not choices:
            return None
        if best is None or len(choices) < len(best):
            best = choices
    for i in best:
        result = cover(remaining.difference(placements[i][1]), placements, lookup)
        if result is not None:
            return [i] + result
    return None
def run(params, grid, demos):
    source = int(round(params['colors'][0]))
    colors = [int(round(v)) for v in params['colors']]
    lengths = [int(round(v)) for v in params['lengths']]
    offsets = [[[int(round(v)) for v in pair] for pair in tile] for tile in params['offsets']]
    cells = set(tuple(p) for p in np.argwhere(grid == source).tolist())
    lookup = {cell: [] for cell in cells}
    placements = []
    for anchor in sorted(cells):
        for kind in range(len(lengths)):
            length = lengths[kind]
            if length <= 0 or length > len(offsets[kind]):
                continue
            occupied = set((anchor[0] + pair[0], anchor[1] + pair[1]) for pair in offsets[kind][:length])
            if len(occupied) != length or not occupied.issubset(cells):
                continue
            index = len(placements)
            placements.append((kind, occupied))
            for cell in occupied:
                lookup[cell].append(index)
    solution = cover(cells, placements, lookup)
    output = grid.copy()
    if solution is None:
        return output
    for index in solution:
        kind, occupied = placements[index]
        color = colors[kind + 1]
        for row, column in occupied:
            output[row, column] = color
    return output

