    if not cells:
        return []
    best = None
    for r, c in cells:
        options = []
        seen = set()
        for k, offsets in enumerate(patterns):
            for dr, dc in offsets:
                ar, ac = r - dr, c - dc
                piece = set((ar + vr, ac + vc) for vr, vc in offsets)
                key = (k, tuple(sorted(piece)))
                if key not in seen and piece.issubset(cells):
                    seen.add(key)
                    options.append((piece, colours[k]))
        if not options:
            return None
        if best is None or len(options) < len(best):
            best = options
    for piece, colour in best:
        result = cover(cells - piece, patterns, colours)
        if result is not None:
            return [(piece, colour)] + result
    return None
