def run(params, grid, demos):
    background = int(round(params['colors'][0]))
    exterior = int(round(params['colors'][1]))
    interior = int(round(params['colors'][2]))
    lower = int(round(params['bounds'][0]))
    inset = int(round(params['bounds'][1]))
    directions = []
    for pair in params['directions']:
        directions.append((int(round(pair[0])), int(round(pair[1]))))
    height, width = grid.shape
    result = grid.copy()
    visited = set()
    for row in range(height):
        for col in range(width):
            if grid[row, col] != background or (row, col) in visited:
                continue
            component = [(row, col)]
            visited.add((row, col))
            touches_border = False
            position = 0
            while position < len(component):
                r, c = component[position]
                position += 1
                if r == lower or c == lower or r == height - inset or c == width - inset:
                    touches_border = True
                for dr, dc in directions:
                    nr, nc = r + dr, c + dc
                    if lower <= nr < height and lower <= nc < width:
                        if grid[nr, nc] == background and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            component.append((nr, nc))
            color = exterior if touches_border else interior
            for r, c in component:
                result[r, c] = color
    return result

