    for column in range(grid.shape[1]):
        if np.all(grid[:, column] == divider):
            cut = column
            break
    if cut is None:
        return grid.copy()
    left = grid[:, :cut]
    right = grid[:, cut + divider_width:]
    if left.shape != right.shape:
        return grid.copy()
    return np.where(left == right, left, np.where(right == background, removed, added))

def run(params, grid, demos):
    background = int(round(params['rule'][0]))
    separator = int(round(params['rule'][1]))
    added = int(round(params['rule'][2]))
    removed = int(round(params['rule'][3]))
    gap = int(round(params['rule'][4]))
    axis = int(round(params['rule'][5]))
    if axis != 0 and axis != 1:
        return grid.copy()
    boundaries = np.argwhere(np.all(grid == separator, axis=axis)).flatten()
    if len(boundaries) == 0:
        return grid.copy()
    cut = int(boundaries[0])
    if axis == 0:
        before = grid[:, :cut].copy()
        after = grid[:, cut + gap:].copy()
    else:
        before = grid[:cut, :].copy()
        after = grid[cut + gap:, :].copy()
    if before.shape != after.shape:
        return grid.copy()
    result = before.copy()
    result[np.logical_and(before != background, after == background)] = removed
    result[np.logical_and(before == background, after != background)] = added
    return result

def run(params, grid, demos):
    bg = int(round(params['colors'][0]))
    wall = int(round(params['colors'][1]))
    gate = int(round(params['colors'][2]))
    fill = int(round(params['colors'][3]))
    moves = []
    for pair in params['moves']:
        moves.append((int(round(pair[0])), int(round(pair[1]))))
    top = int(round(params['start'][0]))
    h, w = grid.shape
    out = grid.copy()
    if top < 0 or top >= h:
        return out
    allowed = grid == bg
    left = moves[2]
    right = moves[3]
    for r in range(h):
        for c in range(w):
            if grid[r, c] == gate:
                a, b = r + left[0], c + left[1]
                x, y = r + right[0], c + right[1]
                if 0 <= a < h and 0 <= b < w and 0 <= x < h and 0 <= y < w:
                    if grid[a, b] == wall and grid[x, y] == wall:
                        allowed[r, c] = True
    queue = []
    seen = set()
    for c in range(w):
        a, b = top + left[0], c + left[1]
        x, y = top + right[0], c + right[1]
        if 0 <= a < h and 0 <= b < w and 0 <= x < h and 0 <= y < w:
            if grid[top, c] == bg and grid[a, b] == wall and grid[x, y] == wall:
                queue.append((top, c))
                seen.add((top, c))
    while queue:
        r, c = queue.pop()
        out[r, c] = fill
        for dr, dc in moves:
            a, b = r + dr, c + dc
            if 0 <= a < h and 0 <= b < w:
                if allowed[a, b] and (a, b) not in seen:
                    seen.add((a, b))
                    queue.append((a, b))
    return out

def run(params, grid, demos):
    background = int(round(params['colors'][0]))
    wall = int(round(params['colors'][1]))
    marker = int(round(params['colors'][2]))
    paint = int(round(params['colors'][3]))
    moves = [(int(round(v[0])), int(round(v[1]))) for v in params['moves']]
    start_row = int(round(params['entry'][0]))
    h, w = grid.shape
    out = grid.copy()
    queue = []
    seen = set()
    if not (0 <= start_row < h):
        return out
    for c in range(w):
        left = c + moves[1][1]
        right = c + moves[2][1]
        if 0 <= left < w and 0 <= right < w:
            if grid[start_row, c] == background and grid[start_row, left] == wall and grid[start_row, right] == wall:
                queue.append((start_row, c))
    while queue:
        r, c = queue.pop()
        if (r, c) in seen:
            continue
        seen.add((r, c))
        value = grid[r, c]
        if value != background and value != marker:
            continue
        if value == marker:
            nr = r + moves[0][0]
            nc = c + moves[0][1]
            if not (0 <= nr < h and 0 <= nc < w):
                continue
            if grid[nr, nc] != background and grid[nr, nc] != marker:
                continue
        out[r, c] = paint
        for dr, dc in moves:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if (nr, nc) not in seen:
                    if grid[nr, nc] == background or grid[nr, nc] == marker:
                        queue.append((nr, nc))
    return out
